#include <cstdint>

struct CtlFields { std::uint32_t deviceType, function, method, access; };

std::uint32_t ctlCode(std::uint32_t deviceType, std::uint32_t function, std::uint32_t method, std::uint32_t access)
{
    return (deviceType << 16) | (access << 14) | (function << 2) | method;
}

CtlFields decode(std::uint32_t code)
{
    return { code >> 16, (code >> 2) & 0xFFFu, code & 0x3u, (code >> 14) & 0x3u };
}

bool isVendorCode(std::uint32_t code)
{
    const CtlFields f{ decode(code) };
    return f.deviceType >= 0x8000 && f.function >= 0x800;
}

unitTests:
TEST("encode") { CHECK_EQ(ctlCode(0x8001, 0x801, 0, 3), 0x8001E004u); CHECK_EQ(ctlCode(0x8001, 0x800, 0, 0), 0x80012000u); }
TEST("decode") { const CtlFields f{ decode(0x8001E004u) }; CHECK_EQ(f.deviceType, 0x8001u); CHECK_EQ(f.function, 0x801u); CHECK_EQ(f.method, 0u); CHECK_EQ(f.access, 3u); }
TEST("round trip") { const CtlFields f{ decode(ctlCode(0x8123, 0xABC, 2, 1)) }; CHECK_EQ(f.deviceType, 0x8123u); CHECK_EQ(f.function, 0xABCu); CHECK_EQ(f.method, 2u); CHECK_EQ(f.access, 1u); }
TEST("a Microsoft code") { CHECK(!isVendorCode(0x00070000u)); CHECK(!isVendorCode(ctlCode(0x8001, 0x10, 0, 0))); CHECK(isVendorCode(ctlCode(0x8001, 0x800, 3, 0))); }

